import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import { Paragraph } from '../../../Typography';
import type { ChipLabelProps } from '../../Chip.types';
import { useChipContext } from '../../hooks';

export const ChipLabel = React.forwardRef<HTMLParagraphElement, ChipLabelProps>(
  (
    { children, className, size = 'small', weight = 'medium', ...props },
    forwardedRef,
  ) => {
    const chipContext = useChipContext();

    if (!chipContext) {
      // eslint-disable-next-line no-console
      console.warn(
        'Missing chip context, make sure that Chip.Label is being used as a child of Chip.Root',
      );
      return null;
    }

    const { disabled } = chipContext;

    return (
      <Paragraph
        {...omitTransientProps(props)}
        ref={forwardedRef}
        className={className}
        role="presentation"
        size={size}
        weight={weight}
        colortype={disabled ? 'disabled' : 'primary'}
      >
        {children}
      </Paragraph>
    );
  },
);

ChipLabel.displayName = 'Chip.Label';
